insert into _xm_s values ($xm${"pricing": {"goldSpotUsdPerOzt": 4178.2, "goldQuoteSource": "gold-api.com", "goldQuoteTimestamp": "2026-09-30T11:21:00Z", "lossFactor": 1.07, "markup": 2.0, "status": "PROVISIONAL", "methodology": "FW 26/27 rule: estimated grams (14K geometry, density-scaled for 10K/18K) x spot per gram x karat fineness x 1.07, plus category labor derived from the owner's 2027 enamel quotes; list price = 2 x cost rounded up to USD 10. Live spot 2026-10-06 was 4169.50 (-0.2%)."}, "approval": {"blockers": ["PROVISIONAL PRICE: labor per category comes from the 2027 enamel quotes; the workshop has not quoted these 30 designs.", "Grams are geometry estimates; no sample has been cast or weighed.", "No images yet: the reference hero and 10 sales frames are generated in Higgsfield after the owner approves the prompts."], "etsyDraftCreationAuthorized": true, "livePublicationAuthorized": false, "authority": "Owner instruction 2026-10-06: Christmas set of 10 rings, 10 bracelets, 10 necklaces with 10 Etsy sales images each (\"sirayla yap hepsini\")."}, "variantSeal": "6610bc62a901c8e2b794acc2c808d844"}$xm$::jsonb, $xm$Metal: solid 10K, 14K or 18K gold in yellow, white or rose.$xm$, $xm$Each piece is made to order and ships free within the United States from New Jersey. Add a gift message at checkout and it ships with the piece.$xm$, $xm$Care: enamel is glass fused to gold. It keeps its colour, but it can chip on a hard knock, so take it off for the gym and the dishes and wipe it with a soft cloth.$xm$, $xm$Care: solid gold does not tarnish. Wipe it with a soft cloth to keep the polish.$xm$, $xm$The product images are design visualizations of the finished piece, and the three-metal image is a colour visualization of the same design in yellow, white and rose gold; the handmade piece may vary slightly.$xm$);

